TWComponent.script:
log.info("*============ NBE IDC =============*");
log.info("*========================================*");
log.info("[DB BPM Audit user tasks -> Log Error ]- start");
log.info("ProcessInstance :" +tw.system.currentProcessInstanceID + " Error : " + tw.system.error.toString(true));
tw.local.errorMSG=String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
log.info("[DB BPM Audit user tasks -> Log Error ]- END");
log.info("*================================================*");

writeLog(" start update in DB BPM Audit user tasks");
writeLog("OWNER_ID "+tw.local.OWNER_ID)
writeLog("TASK_ID "+tw.local.TASK_ID)
writeLog("INSTANCE_ID "+tw.local.INSTANCE_ID)

tw.local.Statuss = true;
tw.local.sqlQuerys = new tw.object.listOf.SQLStatement();

tw.local.sql= "UPDATE "+tw.env.LKP_DB_Schema+".AUDIT_USER_TASKS SET (TASK_ID) = (?) WHERE INSTANCE_ID = ? AND OTHER_GROUP_FILTER = ?;"
	tw.local.sqlQuerys[0]= new tw.object.SQLStatement();
	tw.local.sqlQuerys[0].sql=tw.local.sql;   

	tw.local.sqlQuerys[0].parameters= new tw.object.listOf.SQLParameter();   

	tw.local.sqlQuerys[0].parameters[0]= new tw.object.SQLParameter();
	tw.local.sqlQuerys[0].parameters[0].value=tw.local.TASK_ID.split(".")[1];
	tw.local.sqlQuerys[0].parameters[0].mode="IN"; 
	

	tw.local.sqlQuerys[0].parameters[1]= new tw.object.SQLParameter();
	tw.local.sqlQuerys[0].parameters[1].value= tw.local.INSTANCE_ID ;
	tw.local.sqlQuerys[0].parameters[1].mode="IN"; 
	
	tw.local.sqlQuerys[0].parameters[2]= new tw.object.SQLParameter();
	tw.local.sqlQuerys[0].parameters[2].value= tw.local.stepName ;
	tw.local.sqlQuerys[0].parameters[2].mode="IN"; 


function writeLog(msg , variable){  // vairable is optional
	var instanceID = "";
	try {instanceID = "Instance ID : "+tw.system.currentProcessInstance.id  +"  ::  ";} catch (err) {}
	variable == undefined ? variable =" " : variable = " : "+ variable ;
	var message = instanceID + tw.system.model.processApp.name  +" :: " + tw.system.serviceFlow.type +" :: "+ tw.system.serviceFlow.name +" :: "  + msg+" : " + variable;
	log.debug( message);
}

tw.local.Statuss = true;
tw.local.sqlQuerys = new tw.object.listOf.SQLStatement();

tw.local.sql= "INSERT INTO  "+tw.env.LKP_DB_Schema+".AUDIT_USER_TASKS \
(INSTANCE_ID ,TASK_ID, OWNER_ID, TEAM_NAME , FILTER_BRANCH  , STATUS  , TEAM_MANAGER , OTHER_GROUP_FILTER, PARENT_TEAM_NAME)\
 VALUES  (?,?,?,?,?,?,?,?,?)"
	tw.local.sqlQuerys[0]= new tw.object.SQLStatement();
	tw.local.sqlQuerys[0].sql=tw.local.sql;   

	tw.local.sqlQuerys[0].parameters= new tw.object.listOf.SQLParameter();   
	tw.local.sqlQuerys[0].parameters[0]= new tw.object.SQLParameter();
	tw.local.sqlQuerys[0].parameters[0].value= tw.local.INSTANCE_ID//tw.system.currentProcessInstanceID;
	tw.local.sqlQuerys[0].parameters[0].mode="IN"; 
	
	
	//tw.local.sqlQuerys[0].parameters= new tw.object.listOf.SQLParameter();   
	tw.local.sqlQuerys[0].parameters[1]= new tw.object.SQLParameter();
	tw.local.sqlQuerys[0].parameters[1].value= tw.local.TASK_ID.split(".")[1];//tw.system.currentProcessInstanceID;
	tw.local.sqlQuerys[0].parameters[1].mode="IN"; 
	
	
