	tw.local.sqlQuerys[0].parameters[2].value= tw.local.OWNER_ID//tw.system.currentProcessInstanceID;
	tw.local.sqlQuerys[0].parameters[2].mode="IN"; 
	

	tw.local.sqlQuerys[0].parameters[3]= new tw.object.SQLParameter();
	tw.local.sqlQuerys[0].parameters[3].value=tw.local.TEAM_NAME;
	tw.local.sqlQuerys[0].parameters[3].mode="IN"; 

/*	tw.local.sqlQuerys[0].parameters[3]= new tw.object.SQLParameter();
	tw.local.sqlQuerys[0].parameters[3].value=tw.local.GROUP_NAME;
	tw.local.sqlQuerys[0].parameters[3].mode="IN"; 
*/
	tw.local.sqlQuerys[0].parameters[4]= new tw.object.SQLParameter();
	tw.local.sqlQuerys[0].parameters[4].value=tw.local.FILTER_BRANCH;
	tw.local.sqlQuerys[0].parameters[4].mode="IN"; 

	tw.local.sqlQuerys[0].parameters[5]= new tw.object.SQLParameter();
